import java.util.*;

class Solution {
    public int maxWidthRamp(int[] nums) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < nums.length; i++) {
            if (stack.isEmpty() || nums[i] < nums[stack.peek()]) {
                stack.push(i);
            }
        }

        int best = 0;
        for (int j = nums.length - 1; j >= 0; j--) {
            while (!stack.isEmpty() && nums[stack.peek()] <= nums[j]) {
                best = Math.max(best, j - stack.pop());
            }
        }
        return best;
    }
}

class Solution {
    public int maxWidthRamp(int[] nums) {
        int n = nums.length;
        int[] leftMin = new int[n];
        int[] rightMax = new int[n];

        leftMin[0] = nums[0];
        for (int i = 1; i < n; i++) {
            leftMin[i] = Math.min(leftMin[i - 1], nums[i]);
        }
        rightMax[n - 1] = nums[n - 1];
        for (int j = n - 2; j >= 0; j--) {
            rightMax[j] = Math.max(rightMax[j + 1], nums[j]);
        }

        int best = 0;
        int i = 0;
        int j = 0;
        while (i < n && j < n) {
            if (leftMin[i] <= rightMax[j]) {
                best = Math.max(best, j - i);
                j++;
            } else {
                i++;
            }
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int maxWidthRamp(int[] nums) {
        Integer[] order = new Integer[nums.length];
        for (int i = 0; i < nums.length; i++) {
            order[i] = i;
        }
        Arrays.sort(order, (a, b) -> nums[a] != nums[b]
                ? Integer.compare(nums[a], nums[b])
                : Integer.compare(a, b));

        int minIndex = nums.length;
        int best = 0;
        for (int index : order) {
            best = Math.max(best, index - minIndex);
            minIndex = Math.min(minIndex, index);
        }
        return best;
    }
}

class Solution {
    public int maxWidthRamp(int[] nums) {
        int low = 0;
        int high = nums.length - 1;
        while (low < high) {
            int mid = low + (high - low + 1) / 2;
            if (hasRampAtLeast(nums, mid)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private boolean hasRampAtLeast(int[] nums, int width) {
        int minLeft = nums[0];
        for (int j = width; j < nums.length; j++) {
            minLeft = Math.min(minLeft, nums[j - width]);
            if (minLeft <= nums[j]) {
                return true;
            }
        }
        return width == 0;
    }
}

class Solution {
    public int maxWidthRamp(int[] nums) {
        int best = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] <= nums[j]) {
                    best = Math.max(best, j - i);
                }
            }
        }
        return best;
    }
}
